import java.util.*;

class Solution {
    private static class Node {
        Node[] child = new Node[2];
    }

    public int bestXorPair(int[] nums) {
        Node root = new Node();
        int best = 0;
        for (int x : nums) {
            Node cur = root;
            for (int b = 30; b >= 0; b--) {         // insert x, highest bit first
                int bit = (x >> b) & 1;
                if (cur.child[bit] == null) cur.child[bit] = new Node();
                cur = cur.child[bit];
            }
            cur = root;
            int val = 0;
            for (int b = 30; b >= 0; b--) {         // greedy: try to flip each bit
                int bit = (x >> b) & 1;
                if (cur.child[1 - bit] != null) {
                    val |= 1 << b;
                    cur = cur.child[1 - bit];
                } else {
                    cur = cur.child[bit];
                }
            }
            best = Math.max(best, val);
        }
        return best;
    }
}

