class Solution:
    def bestXorPair(self, nums: List[int]) -> int:
        best = 0
        for b in range(30, -1, -1):
            best <<= 1
            pre = {x >> b for x in nums}
            cand = best | 1
            if any((cand ^ p) in pre for p in pre): best = cand
        return best

