function bestXorPair(nums) {
  const root = [null, null];
  let best = 0;
  for (const x of nums) {
    let n = root;
    for (let b = 30; b >= 0; b--) { const bit = (x >> b) & 1; if (!n[bit]) n[bit] = [null, null]; n = n[bit]; }
    let m = root, v = 0;
    for (let b = 30; b >= 0; b--) { const bit = (x >> b) & 1; if (m[1 - bit]) { v |= (1 << b); m = m[1 - bit]; } else m = m[bit]; }
    if (v >>> 0 > best) best = v >>> 0;
  }
  return best;
}
